<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<?php if (!empty($my_receiving_requests)) { ?><div class="panel panel-piluku"><div class="panel-heading"><h4>Mis recepciones de mercancía</h4></div><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Solicitud</th><th>Fecha</th><th>Importe</th><th>Estado</th><th>Recibo</th></tr></thead><tbody>
<?php foreach ($my_receiving_requests as $request) { ?><tr><td><a href="<?php echo site_url('home/receiving_request/'.$request['id']); ?>">#<?php echo (int)$request['id']; ?></a></td><td><?php echo html_escape($request['receiving_time']); ?></td><td><?php echo to_currency($request['total']); ?></td><td><?php echo $request['status']==='authorized' ? 'Autorizada' : ($request['status']==='rejected' ? 'Rechazada' : 'Pendiente'); ?></td><td><?php if ($request['status']==='authorized' && $request['receiving_id']) { ?><a class="btn btn-success" href="<?php echo site_url('receivings/request_receipt/'.$request['id']); ?>">Imprimir recibo autorizado</a><?php } elseif ($request['status']==='rejected') { echo html_escape($request['rejection_reason']); } else { ?>Esperando al supervisor<?php } ?></td></tr><?php } ?>
</tbody></table></div><small>El estado se actualiza cada 30 segundos. Solo las autorizadas tienen recibo.</small></div></div><?php } ?>
